var vroot = '/'+CONTEXT+'/';
var mroot = vroot+'static/';
var icons = mroot+'/web/icons/';
var xt = Ext;
var xMsg = xt.Msg;
var xPanel = xt.Panel;
var xWindow = xt.Window;
var xPanel = xt.Panel;
var xGrid = xt.grid.GridPanel;
var xDataView = xt.DataView;
var xColumn = xt.grid.ColumnModel;
var xSelection = xt.grid.RowSelectionModel;
