                                //         new xWindow({
                                //             id:'URL-window',
                                //             title: 'Endereço de Post',
                                //             modal:true,
                                //             items:
                                //             [
                                //                 {
                                //                     id:'url-to-copy',
                                //                     xtype:'textfield',
                                //                     fieldLabel: 'URL',
                                //                     selectOnFocus:true,
                                //                     value: record.get('link'),
                                //                     readOnly: true,
                                //                     width:400
                                //                 },
                                //                 {
